<template>
  <div class="user-page">
    <!-- 顶部搜索栏 -->
    <div class="search-bar">
      <span>用户名</span>
      <el-input v-model="searchName" placeholder="用户名" style="width: 200px; margin: 0 10px"></el-input>
      <el-button type="primary" @click="handleSearch">查询用户</el-button>
      <el-button type="success" @click="dialogVisible = true">添加用户</el-button>
    </div>

    <!-- 数据表格 -->
    <el-table :data="tableData" style="width: 100%; margin-top: 20px">
      <el-table-column prop="date" label="日期" width="180">
        <template slot-scope="scope">
          <i class="el-icon-time"></i>
          <span style="margin-left: 10px">{{ scope.row.date }}</span>
        </template>
      </el-table-column>
      <el-table-column prop="name" label="用户名" width="180">
        <template slot-scope="scope">
          <el-tag>{{ scope.row.name }}</el-tag>
        </template>
      </el-table-column>
      <el-table-column prop="password" label="密码" width="180"></el-table-column>
      <el-table-column label="操作">
        <template slot-scope="scope">
          <el-button size="mini" type="primary" plain>编辑</el-button>
          <el-button size="mini" type="danger">删除</el-button>
        </template>
      </el-table-column>
    </el-table>

    <!-- 底部分页 -->
    <div class="pagination">
      <el-pagination
        background
        layout="prev, pager, next"
        :total="1000"
        :page-size="10"
        :current-page="currentPage"
        @current-change="handlePageChange"
      >
      </el-pagination>
    </div>

    <!-- 添加用户弹窗 -->
    <el-dialog
      title="新用户"
      :visible.sync="dialogVisible"
      width="30%"
      :close-on-click-modal="false"
    >
      <el-form label-width="80px">
        <el-form-item label="用户名">
          <el-input v-model="form.name"></el-input>
        </el-form-item>
        <el-form-item label="初始密码">
          <el-input v-model="form.password" type="password"></el-input>
        </el-form-item>
        <el-form-item label="确认密码">
          <el-input v-model="form.checkPass" type="password"></el-input>
        </el-form-item>
      </el-form>
      <div slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="dialogVisible = false">确定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: 'UserView',
  data() {
    return {
      searchName: '',
      currentPage: 1,
      dialogVisible: false,
      form: {
        name: '',
        password: '',
        checkPass: ''
      },
      // 模拟的表格数据
      tableData: [
        { date: '2016-05-02', name: '王小虎', password: '123456' },
        { date: '2016-05-04', name: '王小虎', password: '123456' },
        { date: '2016-05-01', name: '王小虎', password: '123456' },
        { date: '2016-05-03', name: '王小虎', password: '123456' }
      ]
    }
  },
  methods: {
    handleSearch() {
      // 无需实际功能，保留空方法即可
    },
    handlePageChange(page) {
      this.currentPage = page;
    }
  }
}
</script>

<style scoped>
.search-bar {
  display: flex;
  align-items: center;
}
.pagination {
  margin-top: 20px;
  display: flex;
  justify-content: center;
}
</style>
